# Import-Module $ToolsPath\Console.psm1
# Import-Module $ToolsPath\Synchronous-ZipAndUnzip.psm1

# param 
# (
    # [Parameter(Mandatory=$true)]
    # [string] $ZipPathFileName,
    # [Parameter(Mandatory=$false)]
	# [String[]] $Ressources =@()
# )
	$ZipPathFileName = ""
	$Ressources =@()

	$resultCode = 0

	try 
	{		
		<###########################################################################>
		<#                       Chargement des dépendances                        #>
		<###########################################################################>
		$ToolsPath = Split-Path $script:MyInvocation.MyCommand.Path
		
		$ZipPath =  Split-Path -Path $ZipPathFileName -Parent
		
		$now = (Get-Date).toString("yyyyMMdd-HHmmss")
		$LogFileName = "DeployWeb.Net4-"+ $now + ".logs"
		$LogFilePath = Join-Path $ZipPath $LogFileName
		If(!(Test-Path $LogFilePath)){
			New-Item -ItemType File -Force -Path $LogFilePath | Out-Null
		}
		
		<###########################################################################>
		<#                       Détermination de la cible à livrer                #>
		<###########################################################################>
		Console-ShowTitle -Title "Détermination de la cible à livrer" -LogFile $LogFilePath
		
		If (!(Test-Path $ZipPathFileName)) { 
			throw  "Package à livrer introuvable (" + $ZipPathFileName +")"
		}
	
		$file = Get-ChildItem -Path $ZipPathFileName | Select-Object -First 1 Name 
		$ZipFileName = $file.Name
	
		$PackageInfos = $ZipFileName.Split("-")
		If($PackageInfos.Count -lt 3) {
			throw  "Informations manquantes dans le nommage du package (Rappel : <Nom>-<Version>-<Env>.zip)"
		}
		
		$NomWebApp = $PackageInfos[0]
		Console-ShowInfos -Infos "Nom de l'application : $NomWebApp" -LogFile $LogFilePath
		
		$VersionWebApp = $PackageInfos[1]
		$VersionWebapp = $VersionWebApp.Split(".")[0]
		Console-ShowInfos -Infos "Version de l'application : $VersionWebApp" -LogFile $LogFilePath
		
		$EnvWebApp = ($PackageInfos[$PackageInfos.Count - 1]).Replace(".zip", "")
		
		$PathServeurNouvelleInfra = ""
		$SauvegardeNouvelleInfra = ""
		$PathServeurAncienneInfra = ""
		$SauvegardeAncienneInfra = ""
		If ($EnvWebApp -eq "int") {
			Console-ShowInfos -Infos "Environnement : Intégration" -LogFile $LogFilePath
			$SauvegardeAncienneInfra = "I:\Informatique\SI Services\Archives\Cochevis\" + $NomWebApp + "\V" + $VersionWebApp + "\"
			$SauvegardeNouvelleInfra = "I:\Informatique\SI Services\Archives\Wapiti\" + $NomWebApp + "-" + $EnvWebApp + "\V" + $VersionWebApp + "\"
			$PathServeurNouvelleInfra = "\\serv19wstest.ociane.fr\sites$\" + $NomWebApp + "-int\V" + $VersionWebApp + "\"
			$PathServeurAncienneInfra = "\\servwsmatmut.ociane.fr\sites$\" + $NomWebApp + "\V" + $VersionWebApp + "\"
		} ElseIf ($EnvWebApp -eq "hom") {
			Console-ShowInfos -Infos "Environnement : Homologation" -LogFile $LogFilePath
			$SauvegardeAncienneInfra = "I:\Informatique\SI Services\Archives\Ecrevisse\" + $NomWebApp + "\V" + $VersionWebApp + "\"
			$SauvegardeNouvelleInfra = "I:\Informatique\SI Services\Archives\Wapiti\" + $NomWebApp + "-" + $EnvWebApp + "\V" + $VersionWebApp + "\"
			$PathServeurNouvelleInfra = "\\serv19wstest.ociane.fr\sites$\" + $NomWebApp + "-hom\V" + $VersionWebApp + "\"
			$PathServeurAncienneInfra = "\\servwstest.ociane.fr\sites$\" + $NomWebApp + "\V" + $VersionWebApp + "\"
		} ElseIf ($EnvWebApp -eq "pro") {
			Console-ShowInfos -Infos "Environnement : Production" -LogFile $LogFilePath
			$SauvegardeAncienneInfra = "I:\Informatique\SI Services\Archives\Clovisse\" + $NomWebApp + "\V" + $VersionWebApp + "\"
			$SauvegardeNouvelleInfra = "I:\Informatique\SI Services\Archives\Wallaby\" + $NomWebApp + "-" + $EnvWebApp + "\V" + $VersionWebApp + "\"
			$PathServeurNouvelleInfra = "\\serv19ws.ociane.fr\sites$\" + $NomWebApp + "\V" + $VersionWebApp + "\"
			$PathServeurAncienneInfra = "\\servws.ociane.fr\sites$\" + $NomWebApp + "\V" + $VersionWebApp + "\"
		} Else {
			throw  "Environnement demandé inconnu."
		}

		$PathDestination = $PathServeurNouvelleInfra
		$Sauvegarde = $SauvegardeNouvelleInfra
		If (!(Test-Path $PathDestination)) {
			$PathDestination = $PathServeurAncienneInfra
			$Sauvegarde = $SauvegardeAncienneInfra
		}
		
		Console-ShowInfos -Infos "Cible de déploiement : $PathDestination" -LogFile $LogFilePath
		
		If (!(Test-Path $PathDestination)) {
			throw  "Destination " + $PathDestination + " inexistante"
		}
		
		
		<###########################################################################>
		<#                                  IIS Reset                              #>
		<###########################################################################>
		Console-ShowTitle -Title "IIS Reset..." -LogFile $LogFilePath
		
		Console-ShowInfos -Infos "Rafraichissement du web.config." -LogFile $LogFilePath
		Get-ChildItem -Path $PathDestination -File -Include "web.config" | ForEach-Object { (Get-Content $_) | Set-Content $_ }
		
		Console-ShowInfos -Infos "Positionnement de la page de maintenance." -LogFile $LogFilePath
		$OfflinePage = "App_offline.htm"
		$OfflinePagePath = Join-Path $PathDestination $OfflinePage
		Set-Content $OfflinePagePath '<html><head><style>*{margin: 0;padding: 0;box-sizing: border-box;list-style: none;}body{background-color: lightgray;}.container svg{position: absolute;top: 0px;}</style></head><body class="fond"><div class="container"><svg id="truck" xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" width="100%" height="100%"><image width="100%" height="100%" xlink:href="data:image/png;base64,"/></svg><svg id="operator" xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" width="100%" height="100%" style="opacity:0;alpha(opacity=0);"><image width="100%" height="100%" xlink:href="data:image/png;base64,"/></svg><svg id="app" xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" width="100%" height="100%" style="opacity:0;alpha(opacity=0);"><image width="100%" height="100%" xlink:href="data:image/png;base64,"/></svg><svg id="wait" xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" width="100%" height="100%" style="opacity:0;alpha(opacity=0);"><image width="100%" height="100%" xlink:href="data:image/png;base64,"/></svg></div><script type="text/javascript">var i=0;var j=100;var k=100;var id=null;id=window.setInterval(function(){var truck=document.getElementById("truck");truck.style.opacity=(100-i)/100;truck.style.filter="alpha(opacity="+(100-i)+")";var operator=document.getElementById("operator");operator.style.opacity=Math.min(i,j)/100;operator.style.filter="alpha(opacity="+Math.min(i,j)+")";var app=document.getElementById("app");app.style.opacity=Math.min((i-100), k)/100;app.style.filter="alpha(opacity="+Math.min((i-100), k)+")";var wait=document.getElementById("wait");wait.style.opacity=(i-200)/100;wait.style.filter="alpha(opacity="+(i-200)+")";i++;if(100 < i){j--;}if(200 < i){k--;}if(400 < i){location.reload();}}, 50);</script></body></html>'
				
		<###########################################################################>
		<#                       Sauvegarde de la version en cours                 #>
		<###########################################################################>
		Console-ShowTitle -Title "Sauvegarde de la version en cours..." -LogFile $LogFilePath
	
		$RandomBackupName = $NomWebApp + "-" + $VersionWebApp + "-" + (Get-Date).ToString("yyyyMMdd-HHmmss") + "-" + $EnvWebApp + ".zip"
		$RandomBackupPath = Join-Path $PathDestination $RandomBackupName
		
		Console-ShowInfos -Infos "Chemin du fichier de sauvegarde : $RandomBackupPath" -LogFile $LogFilePath

		$Ressources = $Ressources + $OfflinePage
		$Ressources = $Ressources + $RandomBackupName
		
		Console-ShowInfos -Infos "Liste des ressources non sauvegardées : $Ressources" -LogFile $LogFilePath	
		
		Console-ShowInfos -Infos "Sauvegarde du site." -LogFile $LogFilePath
		Get-ChildItem -Path $PathDestination -Exclude $Ressources | ForEach-Object { Compress-ZipFile -ZipFilePath $RandomBackupPath -FileOrDirectoryPathToAddToZipFile $_.Fullname -OverwriteWithoutPrompting }
	
		<###########################################################################>
		<#                       Déploiement du package                            #>
		<###########################################################################>
		Console-ShowTitle -Title "Déploiement du package..." -LogFile $LogFilePath
				
		Console-ShowInfos -Infos "Suppression de tous les fichiers sauf les ressources." -LogFile $LogFilePath
		Remove-Item -Path $PathDestination -Exclude $Ressources -Force -Recurse -Confirm:$false
	
		Console-ShowInfos -Infos "Copie du package à déployer dans la destination." -LogFile $LogFilePath
		Copy-Item $ZipPathFileName -Destination $PathDestination
	
		Console-ShowInfos -Infos "Décompression dans la destination." -LogFile $LogFilePath
		$ZipInPathDestination = Join-Path $PathDestination $ZipFileName
		Expand-ZipFile -ZipFilePath $ZipInPathDestination -DestinationDirectoryPath $PathDestination -OverwriteWithoutPrompting
	    
		Console-ShowGoodNews -GoodNews "Fin du script avec succès !" -LogFile $LogFilePath
	}
	catch {
		Console-ShowError -Message '[Erreur] Le déploiement du projet a été interrompu pour les raisons suivantes : ' -Error $_ -LogFile $LogFilePath
		$resultCode = 1
	}
	finally {

		If($null -ne $RandomBackupPath -and (Test-Path $RandomBackupPath)){
			$Sauvegarde = Join-Path $Sauvegarde $RandomBackupName			
			Console-ShowInfos -Infos "Déplacement du zip dans le dossier de sauvegarde ($Sauvegarde)" -LogFile $LogFilePath
			Move-Item -Path $RandomBackupPath -Destination $Sauvegarde -Force
		}
		
		If($null -ne $ZipInPathDestination -and (Test-Path $ZipInPathDestination)){		
			Console-ShowInfos -Infos "Suppression du zip déployé" -LogFile $LogFilePath
			Remove-Item $ZipInPathDestination -Force
		}
		
		If($null -ne $OfflinePagePath -and (Test-Path $OfflinePagePath)){
			Console-ShowInfos -Infos "Suppression de la page de maintenance." -LogFile $LogFilePath			
			Remove-Item $OfflinePagePath  -Force
		}
		
		If($null -ne $LogFilePath -and (Test-Path $LogFilePath)){
			$NouveauLogPath = Join-Path $ZipPath $ZipFileName.Replace(".zip", "-" + $now + ".logs")
			Move-Item -Path $LogFilePath -Destination $NouveauLogPath -Force
		}
	}

	Exit $resultCode